function quando(sec){const d=new Date(sec*1000),n=new Date(nowS()*1000),h=d.toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'});if(d.toDateString()==n.toDateString())return'oggi alle '+h;const g=(d-n)/864e5;return(g<6?d.toLocaleDateString('it-IT',{weekday:'long'}):d.toLocaleDateString('it-IT',{day:'numeric',month:'long'}))+' alle '+h}
function pezzo(c,w){const k=c&&c[w];if(!k)return null;const fine=k.reset||0,att=fine&&fine<nowS();return{pct:att?0:Math.max(0,k.pct),fine:fine,att:att,vecchio:false}}
function claudeCal(){const c=PLV().claude&&PLV().claude.sette_giorni;if(!c||!c.reset||c.reset<nowS()||c.pct<3||!CR)return null;const ini=c.reset-7*86400,L=CR.righe.filter(x=>x.f=='claude'&&rowTs(x)>=ini&&rowTs(x)<=c.reset).reduce((a,x)=>a+x.L,0);return L>0?{perPct:L/c.pct,L:L,pct:c.pct,ini:ini,fin:c.reset}:null}
