function costoRiga(x){const cal=claudeCal();if(x.f=='claude'&&cal)return{p:x.L/cal.perPct,u:'della settimana'};if(isCp(x)){const u=copilotUso();if(u&&u.used!=null&&u.per(x)>0)return{p:u.per(x)*100/u.tetto,u:'del mese'}}return null}
