const norm=s=>String(s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,''),STOPW=['fermati','stop','aspetta','annulla','sbagliato','sbagliata','sbagliati'];
function lev1(a,b){if(a==b)return true;if(Math.abs(a.length-b.length)>1)return false;let i=0,j=0,e=0;while(i<a.length&&j<b.length){if(a[i]==b[j]){i++;j++;continue}if(++e>1)return false;if(a.length>b.length)i++;else if(a.length<b.length)j++;else{i++;j++}}return e+(a.length-i)+(b.length-j)<=1}
function interrompe(d){const t=norm(d).slice(0,80);if(/(torna indietro|non cosi|non volevo|non intendevo|non era (questo|quello)|^no[ ,.!]|sbagliat)/.test(t))return true;return t.split(/[^a-z]+/).filter(w=>w.length>=4).some(w=>STOPW.some(k=>w==k||(k.length>=6&&lev1(w,k))))}
